parameters.jsCode:
// Decodifica a resposta da IA e normaliza metadados do chamado
const rawOutput = $json.output || $json.text || '';
let parsed = {};

const ragData = $('Motor RAG (Busca Manual)').first().json;

try {
  const clean = String(rawOutput).replace(/\`\`\`json/g, '').replace(/\`\`\`/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {
    mensagem_whatsapp: typeof rawOutput === 'string' && rawOutput.length > 5 ? rawOutput : `Recebi sua mensagem. Poderia me informar mais detalhes para que possamos te orientar ou registrar o chamado?`,
    acao: 'saudacao'
  };
}

const respostaTexto = parsed.resposta_whatsapp || parsed.mensagem_whatsapp || parsed.resposta || (typeof rawOutput === 'string' ? rawOutput : 'Olá! Como posso te ajudar hoje?');

// Extração com Fallback Inteligente direto do texto do Protocolo emitido pela IA
// Aceita bullets: •, -, *, 1., etc.
const matchUnidade = respostaTexto.match(/[•\-\*	 ]*\*?Unidade:\*?\s*([^\n\r]+)/i);
const matchSetor = respostaTexto.match(/[•\-\*	 ]*\*?Setor:\*?\s*([^\n\r]+)/i);
const matchEquipCat = respostaTexto.match(/[•\-\*	 ]*\*?(?:Equipamento\/Categoria|Categoria\/Equipamento|Equipamento|Categoria):\*?\s*([^\n\r]+)/i);
const matchProblema = respostaTexto.match(/[•\-\*	 ]*\*?(?:Problema|Defeito|Descrição|Motivo):\*?\s*([^\n\r]+)/i);

const nomeFinal = parsed.nome_capturado || parsed.nome || ragData.nome || 'Solicitante';

let unidadeFinal = parsed.unidade_capturada || parsed.unidade;
if (!unidadeFinal && matchUnidade && matchUnidade[1]) {
  unidadeFinal = matchUnidade[1].replace(/\(se houver\)/i, '').replace(/\*/g, '').trim();
}
if (!unidadeFinal || unidadeFinal === 'Ainda não informada') {
  unidadeFinal = ragData.unidade || 'Secretaria de Saúde';
}

let setorFinal = parsed.setor_capturado || parsed.setor || '';
if (!setorFinal && matchSetor && matchSetor[1] && !matchSetor[1].includes('se houver')) {
  setorFinal = matchSetor[1].replace(/\*/g, '').trim();
}

if (setorFinal && /secretaria|sms|sede/i.test(unidadeFinal) && !unidadeFinal.toLowerCase().includes(setorFinal.toLowerCase())) {
  unidadeFinal = `${unidadeFinal} - Setor ${setorFinal}`;
}

// Extração de Categoria e Equipamento
let categoriaFinal = parsed.categoria;
let equipamentoFinal = parsed.equipamento;

if (matchEquipCat && matchEquipCat[1]) {
  const rawCat = matchEquipCat[1].replace(/\*/g, '').trim();
  const matchParen = rawCat.match(/(.*?)\s*\((.*?)\)/);
  if (matchParen) {
    if (!categoriaFinal) categoriaFinal = matchParen[1].trim();
    if (!equipamentoFinal) equipamentoFinal = matchParen[2].trim();
  } else if (!categoriaFinal) {
    categoriaFinal = rawCat;
  }
}

if (!categoriaFinal) categoriaFinal = 'Hardware e Periféricos';
if (!equipamentoFinal) equipamentoFinal = 'Geral';

// Extração robusta do Problema (evita 'fiz o teste' ou mensagens isoladas de conversa)
let problemaFinal = parsed.problema || parsed.problema_resumido;
if (matchProblema && matchProblema[1]) {
  const problemaProtocolo = matchProblema[1].replace(/\*/g, '').trim();
  if (problemaProtocolo && !/^(fiz|tentei|ja fiz|continua|nao deu|nao foi|continua sem funcionar|nao funcionou|nao resolveu|nao voltou)/i.test(problemaProtocolo)) {
    problemaFinal = problemaProtocolo;
  }
}

const isVagueProblem = !problemaFinal || /^(fiz|tentei|ja fiz|continua|nao deu|nao foi|continua sem funcionar|nao funcionou|nao resolveu|nao voltou|ok|ola|bom dia|boa tarde)/i.test(String(problemaFinal).trim());

if (isVagueProblem) {
  if (matchProblema && matchProblema[1] && !/^(fiz|tentei|continua|nao voltou)/i.test(matchProblema[1].trim())) {
    problemaFinal = matchProblema[1].replace(/\*/g, '').trim();
  } else if (/internet|rede|conectividade|modem|switch/i.test(categoriaFinal) || /internet|rede|modem/i.test(ragData.ragContext || '') || /internet|sem rede|sem conexao/i.test(ragData.mensagem || '')) {
    if (/toda a unidade|toda unidade|todos os computadores/i.test(ragData.mensagem || '') || /KB-RED-GERAL/i.test(ragData.ragContext || '')) {
      problemaFinal = 'Unidade sem Internet';
    } else {
      problemaFinal = setorFinal ? `Computador do setor ${setorFinal} sem internet` : 'Computador sem Internet';
    }
  } else if (/impressora/i.test(categoriaFinal)) {
    problemaFinal = (equipamentoFinal && equipamentoFinal !== 'Geral') ? `${equipamentoFinal} com defeito / sem imprimir` : 'Impressora com defeito';
  } else if (equipamentoFinal && equipamentoFinal !== 'Geral') {
    problemaFinal = `${equipamentoFinal} com defeito relatado`;
  } else {
    problemaFinal = 'Suporte Técnico Presencial';
  }
}

// Tentativa RAG / Testes realizados dinâmicos (sem hardcode)
let tentativaRagFinal = parsed.tentativa_rag || parsed.tentativaRag || parsed.procedimento_nivel_1;
if (!tentativaRagFinal) {
  if (/mouse|teclado|porta usb|cabo usb/i.test(problemaFinal) || /mouse|teclado/i.test(equipamentoFinal)) {
    tentativaRagFinal = 'Testes básicos em outras portas USB e reconexão de hardware';
  } else if (/anydesk|remoto/i.test(problemaFinal) || /impressora.*instala/i.test(problemaFinal)) {
    tentativaRagFinal = 'Instalação / Suporte Remoto via AnyDesk';
  } else if (/impressora|canon|kyocera|brother/i.test(categoriaFinal)) {
    tentativaRagFinal = 'Verificação de conexão na rede da Prefeitura e suprimentos';
  } else if (/rede|internet/i.test(categoriaFinal)) {
    tentativaRagFinal = 'Verificação de cabo de rede / reinicialização do modem';
  } else {
    tentativaRagFinal = 'Triagem Nível 1 realizada via WhatsApp';
  }
}

const isCriarChamado = parsed.acao === 'criar_chamado' || Boolean(matchProblema);

return [{
  json: {
    ...parsed,
    acao: isCriarChamado ? 'criar_chamado' : (parsed.acao || 'saudacao'),
    resposta_whatsapp: respostaTexto,
    telefone: ragData.telefone,
    instance_name: ragData.instance_name || 'suporte-chamados',
    nome: nomeFinal,
    unidade: unidadeFinal,
    setor: setorFinal,
    problema: problemaFinal,
    categoria: categoriaFinal,
    equipamento: equipamentoFinal,
    urgencia: parsed.prioridade ? parsed.prioridade.toLowerCase() : (parsed.urgencia ? parsed.urgencia.toLowerCase() : 'media'),
    tentativa_rag: tentativaRagFinal
  }
}];
